import { marked } from 'marked';

export type Book = {
	slug: string;
	title: string;
	author: string;
	year: number;
	rating: number;
	tags: string[];
};

const files = import.meta.glob('/content/books/*.md', {
	eager: true,
	query: '?raw',
	import: 'default'
}) as Record<string, string>;

function parse(slug: string, raw: string): Book & { body: string } {
	const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/.exec(raw);
	const meta: Record<string, string> = {};
	for (const line of (m?.[1] ?? '').split(/\r?\n/)) {
		const i = line.indexOf(':');
		if (i > 0) meta[line.slice(0, i).trim()] = line.slice(i + 1).trim();
	}
	const unquote = (s: string) => s.replace(/^(['"])(.*)\1$/, '$2');
	const tags = (meta.tags ?? '')
		.replace(/^\[|\]$/g, '')
		.split(',')
		.map((t) => unquote(t.trim()))
		.filter(Boolean);
	return {
		slug,
		title: unquote(meta.title ?? slug),
		author: unquote(meta.author ?? ''),
		year: Number(meta.year),
		rating: Number(meta.rating),
		tags,
		body: m?.[2] ?? ''
	};
}

const all = Object.entries(files).map(([path, raw]) =>
	parse(path.split('/').pop()!.replace(/\.md$/, ''), raw)
);

const byTitle = (a: Book, b: Book) => (a.title < b.title ? -1 : a.title > b.title ? 1 : 0);

export function listBooks(): Book[] {
	return all.map(({ body, ...b }) => b).sort(byTitle);
}

export function topRated(n: number): Book[] {
	return listBooks()
		.sort((a, b) => b.rating - a.rating || byTitle(a, b))
		.slice(0, n);
}

export function getBook(slug: string) {
	const b = all.find((x) => x.slug === slug);
	if (!b) return undefined;
	const { body, ...meta } = b;
	return { ...meta, html: marked.parse(body, { async: false }) as string };
}
EOF
