export type Errors = { name?: string; email?: string; message?: string };

export function validate(name: string, email: string, message: string): Errors {
	const errors: Errors = {};
	if (!name.trim()) errors.name = 'Name is required.';
	if (!email.trim()) errors.email = 'Email is required.';
	else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim()))
		errors.email = 'Enter a valid email address.';
	if (message.trim().length < 20) errors.message = 'Message must be at least 20 characters.';
	return errors;
}
