import { fail } from '@sveltejs/kit';
import { validate } from '#lib/contact';

export const actions = {
	default: async ({ request }) => {
		const data = await request.formData();
		const s = (k: string) => String(data.get(k) ?? '');
		const values = { name: s('name'), email: s('email'), message: s('message') };
		const errors = validate(values.name, values.email, values.message);
		if (Object.keys(errors).length) return fail(400, { values, errors, success: false });
		return { values, errors: {}, success: true, name: values.name.trim() };
	}
};
